insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('JP', 'default', '日本 参照勘定科目表（会社計算規則準拠）', '{"en":"Japan reference chart of accounts (Ordinance on Company Accounting)"}'::jsonb, true, 'companies', array['JP-KSK-BS', 'JP-KSK-PL']::text[], null, 'Japan prescribes no chart of accounts. 会社計算規則 (Ordinance on Company Accounting) prescribes the sections and the main items of the balance sheet of a 株式会社 (arts. 73 to 76) and of its income statement (arts. 88 to 94), and leaves every other subdivision to ''an appropriate name''. This chart is original: four digits by class — 1 assets, 2 liabilities, 3 net assets, 4 revenue and gains, 5 cost of sales, 6 selling and administrative expenses, 7 non-operating and extraordinary expenses, 8 income taxes — cut so that each range reaches one item of those articles, with the account names Japanese bookkeeping uses. No published chart, official or commercial, was copied. The books are kept tax-exclusive (税抜経理): the consumption tax collected sits on 仮受消費税等 and the tax paid on 仮払消費税等 until the return settles them.', 'company-accounting')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

