  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('JP', 'JP-CT-KAKUTEI', '消費税及び地方消費税の確定申告書（一般用）', array['month', 'quarter', 'year']::declaration_period[], 'year'::declaration_period, date '2023-10-01', null, '消費税法 art. 45(1) — a business files a return for each taxable period within two months of its end, stating the 課税標準額 by rate, the tax on it, the deductions (the tax on purchases, on returns and on bad debts), the net and, where interim returns were filed, what remains. Art. 19(1) — the taxable period is the calendar year for an individual and the business year for a company; a business may shorten it to three months or one month by notification (art. 19(1)(iii) to (iv-2)). The law gives the annual period to everybody, which is what period_default says; but a cadence here is anchored on 1 January and a company''s business year is not, so a company whose year runs from April files its return on an annual period the list cannot name, and records it as undecided (see docs/international.md). This is the return for the general method (一般用) with its 付表1-3 and 2-3, the layout since 1 October 2023; the simplified method (簡易課税, art. 37) and the 20 % special measure for businesses that became taxable by registering (2割特例, now the 30 % one for individuals) are other forms or other lines and are not carried. Interim returns (art. 42: eleven monthly ones above 48 million yen of prior-year tax, three quarterly ones above 4 million, one half-yearly above 480,000) are a different form filed on a figure of the previous year and are not declared; what they paid enters ⑩ and ㉑, which stay empty.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, 28, '消費税法 art. 45(1) — the return is filed within two months of the day after the end of the taxable period: for a year ending on 31 March, by 31 May. The vocabulary has no ''two months'', so the pack declares the last day of the following month plus 28 days, which is the 28th of the second month: never later than the law, and one to three days early. Art. 45-2 extends it by one month for a company that has the extension of its corporation tax return and notifies it; an individual files by 31 March of the following year (Ministry of Finance, 消費税に関する基本的な資料, 申告・納付). Neither is expressible, and both are recorded in docs/international.md.', 'ctax-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('JP', 'JP-CT-KAKUTEI', 'F11A', 'base', '課税資産の譲渡等の対価の額（6.24%適用分）', '{"en":"Value of taxable supplies (6.24 %)"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), II ■1 — 付表1-3 ①-1 column A: the value of reduced-rate taxable sales without tax. The guide works it out as the tax-inclusive sales × 100/108; the ledger holds the value without tax, which is what the accumulation method starts from. Transferred to 第二表 ⑤.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'F11B', 'base', '課税資産の譲渡等の対価の額（7.8%適用分）', '{"en":"Value of taxable supplies (7.8 %)"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), II ■1 — 付表1-3 ①-1 column B, the same at the standard rate. Transferred to 第二表 ⑥.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'F11X', 'base', '課税資産の譲渡等の対価の額（旧税率分）', '{"en":"Value of taxable supplies (former rates)"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '付表1-1 (税率別消費税額計算表 〔経過措置対象課税資産の譲渡等を含む課税期間用〕), the columns of the former rates of 3 %, 4 % and 6.3 %: a period that still contains a supply taxed at a former rate files 付表1-1 and 2-1 instead of 1-3 and 2-3. One box for all former rates, which the form prints in separate columns.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'F12', 'base', '特定課税仕入れに係る支払対価の額', '{"en":"Consideration for specified taxable purchases"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), and 付表1-3 記載要領 2(2) — 付表1-3 ①-2, filled only by a business whose taxable sales ratio is below 95 % and that received a 特定課税仕入れ; it is part of the 課税標準額 (消費税法 art. 45(1)(i)).', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'F2A', 'tax', '消費税額（6.24%適用分）', '{"en":"Consumption tax (6.24 %)"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), II ■3 — 付表1-3 ② column A. The guide multiplies the 課税標準額 by 6.24 %; under 消費税法 art. 45(5) and 消費税法施行令 art. 62 a business that keeps copies of the qualified invoices it issued may instead take the total of the tax on them × 78/100, which is what the postings write. Transferred to 第二表 ⑮.', 'ctax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'F2B', 'tax', '消費税額（7.8%適用分）', '{"en":"Consumption tax (7.8 %)"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), II ■3 — 付表1-3 ② column B, at 7.8 %, including the tax on a 特定課税仕入れ; the same accumulation method. Transferred to 第二表 ⑯.', 'ctax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'F2X', 'tax', '消費税額（旧税率分）', '{"en":"Consumption tax (former rates)"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '付表1-1, the tax of the former-rate columns; see F11X.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'F51', 'tax', '売上げの返還等対価に係る税額', '{"en":"Tax on sales returns"}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■3 — 付表1-3 ⑤-1: the tax contained in a return, discount or rebate on a taxable sale (消費税法 art. 38), deducted rather than netted against ①-1. A sale credit note posts its national tax here; the guide''s alternative of reducing the sales directly is not taken.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G1', 'base', '課税売上額（税抜き）', '{"en":"Taxable sales without tax"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■1 — 付表2-3 ①: taxable sales without tax, net of returns. Every domestic sale posts here beside 付表1-3 ①-1, and a sale credit note subtracts its base here only.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G2', 'base', '免税売上額', '{"en":"Exempt sales"}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■2 — 付表2-3 ②: sales exempt under 消費税法 art. 7 and art. 8.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G4', 'total', '課税資産の譲渡等の対価の額', '{"en":"Value of taxable supplies"}'::jsonb, 110, null, array['G1', 'G2']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■3 — 付表2-3 ④ = ① + ② + ③; ③ (non-taxable exports and transfers to a branch abroad) is not carried. Transferred to 第一表 ⑮.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G6', 'base', '非課税売上額', '{"en":"Non-taxable sales"}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■5 — 付表2-3 ⑥: non-taxable sales that enter the denominator of the taxable sales ratio.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G7', 'total', '資産の譲渡等の対価の額', '{"en":"Value of all supplies"}'::jsonb, 130, null, array['G4', 'G6']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■6 — 付表2-3 ⑦ = ⑤ + ⑥, ⑤ being ④. Transferred to 第一表 ⑯.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G10A', 'tax', '課税仕入れに係る消費税額（6.24%適用分）', '{"en":"Consumption tax on taxable purchases (6.24 %)"}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■9 — 付表2-3 ⑩ column A, net of purchase returns. The guide computes it from tax-inclusive purchases × 6.24/108; 消費税法施行令 art. 46(1) makes the accumulation of the invoices'' tax × 78/100 the rule, which is what the postings write.', 'ctax-order'),
  ('JP', 'JP-CT-KAKUTEI', 'G10B', 'tax', '課税仕入れに係る消費税額（7.8%適用分）', '{"en":"Consumption tax on taxable purchases (7.8 %)"}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■9 — 付表2-3 ⑩ column B; the same.', 'ctax-order'),
  ('JP', 'JP-CT-KAKUTEI', 'G10X', 'tax', '課税仕入れに係る消費税額（旧税率分）', '{"en":"Consumption tax on taxable purchases (former rates)"}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '付表2-1, the former-rate columns; see F11X.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G12A', 'tax', '経過措置により課税仕入れに係る消費税額とみなされる額（6.24%適用分）', '{"en":"Tax deemed paid under the transitional measure (6.24 %)"}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■11 — 付表2-3 ⑫ column A: the share of the tax on purchases from businesses that are not qualified invoice issuers deducted under the transitional measure (80 % until 30 September 2026, then 70 %, 50 % and 30 %).', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G12B', 'tax', '経過措置により課税仕入れに係る消費税額とみなされる額（7.8%適用分）', '{"en":"Tax deemed paid under the transitional measure (7.8 %)"}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■11 — 付表2-3 ⑫ column B.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G13', 'base', '特定課税仕入れに係る支払対価の額', '{"en":"Consideration for specified taxable purchases"}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '付表2-3 記載要領 2(4) — 付表2-3 ⑬, filled only below a taxable sales ratio of 95 %.', 'form-2-3-notes'),
  ('JP', 'JP-CT-KAKUTEI', 'G14', 'tax', '特定課税仕入れに係る消費税額', '{"en":"Consumption tax on specified taxable purchases"}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '付表2-3 記載要領 2(4) — 付表2-3 ⑭: 7.8 % of ⑬ (消費税法 art. 30(1)).', 'form-2-3-notes'),
  ('JP', 'JP-CT-KAKUTEI', 'G15A', 'tax', '課税貨物に係る消費税額（6.24%適用分）', '{"en":"Consumption tax on imported goods (6.24 %)"}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■9 (注1) — 付表2-3 ⑮: the tax charged on goods taken out of a bonded area.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G15B', 'tax', '課税貨物に係る消費税額（7.8%適用分）', '{"en":"Consumption tax on imported goods (7.8 %)"}'::jsonb, 220, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■9 (注1) — 付表2-3 ⑮ column B.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G17A', 'total', '課税仕入れ等の税額の合計額（6.24%適用分）', '{"en":"Total tax on purchases (6.24 %)"}'::jsonb, 230, null, array['G10A', 'G12A', 'G15A']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■12 — 付表2-3 ⑰ = ⑩ + ⑫ + ⑭ + ⑮ ± ⑯, column A; ⑯ (the inventory adjustment on entering or leaving the exemption) is not carried.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G17B', 'total', '課税仕入れ等の税額の合計額（7.8%適用分）', '{"en":"Total tax on purchases (7.8 %)"}'::jsonb, 240, null, array['G10B', 'G12B', 'G14', 'G15B']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), III ■12 — 付表2-3 ⑰, column B.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'G17X', 'total', '課税仕入れ等の税額の合計額（旧税率分）', '{"en":"Total tax on purchases (former rates)"}'::jsonb, 250, null, array['G10X']::text[], '{}'::text[], null, null, false, false, null, '付表2-1, the former-rate columns.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K1', 'total', '課税標準額', '{"en":"Taxable amount"}'::jsonb, 260, null, array['F11A', 'F11B', 'F11X', 'F12']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), II ■2 and VI ■1 — 第一表 ①, from 第二表 ①: 付表1-3 ①-1 plus ①-2 (消費税法 art. 45(1)(i)). The form truncates each rate''s amount to the thousand yen (国税通則法 art. 118(1)); a total cannot express that and the pack reports the yen.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K2', 'total', '消費税額', '{"en":"Consumption tax"}'::jsonb, 270, null, array['F2A', 'F2B', 'F2X']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■1 — 第一表 ②, from 第二表 ⑪ = 付表1-3 ② column C.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K3', 'tax', '控除過大調整税額', '{"en":"Adjustment for excess deductions"}'::jsonb, 280, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■1 — 第一表 ③: excess deductions to be added back (付表2-3 ㉗ and ㉘). Declared and empty.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K4', 'total', '控除対象仕入税額', '{"en":"Deductible tax on purchases"}'::jsonb, 290, null, array['G17A', 'G17B', 'G17X']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■2 — 第一表 ④ = 付表2-3 ㉖. Where taxable sales are 500 million yen or less and the taxable sales ratio is 95 % or more, ㉖ is ⑰ (III ■13; 消費税法 art. 30(2)); below that it is apportioned (個別対応方式 or 一括比例配分方式), which the pack does not compute.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K5', 'total', '返還等対価に係る税額', '{"en":"Tax on returns"}'::jsonb, 300, null, array['F51']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■1 — 第一表 ⑤, from 第二表 ⑰ = 付表1-3 ⑤; ⑤-2 (returns on a 特定課税仕入れ) is not carried.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K6', 'tax', '貸倒れに係る税額', '{"en":"Tax on bad debts"}'::jsonb, 310, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■5 — 第一表 ⑥: the tax in a bad debt written off (消費税法 art. 39). Declared and empty: a write-off is not a document the pack taxes.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K7', 'total', '控除税額小計', '{"en":"Total deductions"}'::jsonb, 320, null, array['K4', 'K5', 'K6']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■6 — 第一表 ⑦ = ④ + ⑤ + ⑥.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K8', 'total', '控除不足還付税額', '{"en":"Refund of deductions in excess"}'::jsonb, 330, null, array['K7']::text[], array['K2', 'K3']::text[], null, null, true, false, null, '消費税法 art. 45(1)(v) and 第一表 ⑧: the shortfall when the deductions exceed the tax, ⑦ − ② − ③.', 'ctax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'K9', 'total', '差引税額', '{"en":"Net tax"}'::jsonb, 340, null, array['K2', 'K3']::text[], array['K7']::text[], null, null, true, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■7 — 第一表 ⑨ = ② + ③ − ⑦, truncated to the hundred yen (国税通則法 art. 119(1)); the truncation is not expressible and the pack reports the yen.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K10', 'tax', '中間納付税額', '{"en":"Interim tax paid"}'::jsonb, 350, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■1 ⑴ — 第一表 ⑩: the national tax declared on the interim returns of the period (消費税法 art. 42). Declared and empty: an interim return is filed on a figure from the previous year, not on this period''s documents.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K11', 'total', '納付税額', '{"en":"Tax payable"}'::jsonb, 360, null, array['K9']::text[], array['K10']::text[], null, null, true, false, null, '消費税法 art. 45(1)(vi) and 第一表 ⑪ = ⑨ − ⑩.', 'ctax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'K12', 'total', '中間納付還付税額', '{"en":"Refund of interim tax"}'::jsonb, 370, null, array['K10']::text[], array['K9']::text[], null, null, true, false, null, '消費税法 art. 45(1)(vii) and 第一表 ⑫ = ⑩ − ⑨.', 'ctax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'K15', 'total', '課税資産の譲渡等の対価の額', '{"en":"Value of taxable supplies (ratio numerator)"}'::jsonb, 380, null, array['G4']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■1 — 第一表 ⑮, from 付表2-3 ④ (the numerator of the taxable sales ratio).', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K16', 'total', '資産の譲渡等の対価の額', '{"en":"Value of all supplies (ratio denominator)"}'::jsonb, 390, null, array['G7']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■1 — 第一表 ⑯, from 付表2-3 ⑦ (its denominator).', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K17', 'total', '地方消費税の課税標準となる消費税額（控除不足還付税額）', '{"en":"Local tax base — refund of deductions in excess"}'::jsonb, 400, null, array['K8']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■2 — 第一表 ⑰ = 付表1-3 ⑩, which is ⑧.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K18', 'total', '地方消費税の課税標準となる消費税額（差引税額）', '{"en":"Local tax base — net tax"}'::jsonb, 410, null, array['K9']::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■2 — 第一表 ⑱ = 付表1-3 ⑪, which is ⑨.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'LS', 'tax', '（計算用）地方消費税相当額（売上げ）', '{"en":"Local share of the tax on sales"}'::jsonb, 420, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a box of the form: the 22/78 share of the tax on sales that the postings split off, so that the 譲渡割額 can be summed. 地方税法 art. 72-83 sets the local tax at 22/78 of the national tax; the form works it out as ⑱ × 22/78 truncated to the hundred yen, which a total cannot multiply. Summing the shares gives the same figure to within the roundings of each invoice. It is not hidden, because a box a posting writes into may not be: vat_return() prints it as a working line marked （計算用）.', 'local-tax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'LP', 'tax', '（計算用）地方消費税相当額（仕入れ）', '{"en":"Local share of the deductible tax"}'::jsonb, 430, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a box of the form: the 22/78 share of the deductible tax; see LS.', 'local-tax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'LR', 'tax', '（計算用）地方消費税相当額（売上げの返還等）', '{"en":"Local share of the tax on sales returns"}'::jsonb, 440, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a box of the form: the 22/78 share of the tax on sale returns; see LS.', 'local-tax-act'),
  ('JP', 'JP-CT-KAKUTEI', 'K19', 'total', '還付額（譲渡割額）', '{"en":"Local consumption tax refundable"}'::jsonb, 450, null, array['LP', 'LR']::text[], array['LS']::text[], null, null, true, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■2 — 第一表 ⑲ = 付表1-3 ⑫: the local tax refunded, ⑰ × 22/78; here the local shares summed.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K20', 'total', '納税額（譲渡割額）', '{"en":"Local consumption tax payable"}'::jsonb, 460, null, array['LS']::text[], array['LP', 'LR']::text[], null, null, true, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), IV ■9 and VI ■2 — 第一表 ⑳ = 付表1-3 ⑬: ⑪ × 22/78 truncated to the hundred yen; here the local shares summed.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K21', 'tax', '中間納付譲渡割額', '{"en":"Interim local consumption tax paid"}'::jsonb, 470, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■2 ⑴ — 第一表 ㉑: the local tax declared on the interim returns. Declared and empty, as ⑩.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K22', 'total', '納付譲渡割額', '{"en":"Local consumption tax due"}'::jsonb, 480, null, array['K20']::text[], array['K21']::text[], null, null, true, false, null, '第一表 ㉒ = ⑳ − ㉑.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K23', 'total', '中間納付還付譲渡割額', '{"en":"Refund of interim local consumption tax"}'::jsonb, 490, null, array['K21']::text[], array['K20']::text[], null, null, true, false, null, '第一表 ㉓ = ㉑ − ⑳.', 'form-guide'),
  ('JP', 'JP-CT-KAKUTEI', 'K26', 'total', '消費税及び地方消費税の合計（納付又は還付）税額', '{"en":"Total consumption tax and local consumption tax payable or refundable"}'::jsonb, 500, null, array['K11', 'K22']::text[], array['K8', 'K12', 'K19', 'K23']::text[], null, null, false, false, null, '消費税及び地方消費税の申告書（一般用）の書き方 (NTA, November 2025), VI ■3 — 第一表 ㉖ = (⑪ + ㉒) − (⑧ + ⑫ + ⑲ + ㉓), with a minus sign when it is a refund.', 'form-guide')
