  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('JP-KSK-BS', 'JP', 'default', '貸借対照表（会社計算規則）', 'balance_sheet', 'JP-KAISHA-KEISAN', date '1970-01-01', null, '会社計算規則 (Ordinance on Company Accounting, Ministry of Justice Ordinance No. 13 of 2006), arts. 72 to 86 — the balance sheet of a 株式会社 is divided into assets, liabilities and net assets (art. 73), assets into current, fixed and deferred (art. 74), liabilities into current and fixed (art. 75), net assets into shareholders'' equity, valuation and translation adjustments, share acquisition rights and 株式引受権 (art. 76). The Ordinance prescribes the sections and some items and leaves the rest to ''appropriate items'', so the lines below are its items and the subdivisions Japanese practice prints. 会社法 art. 435(2) is what requires the statements; the Ordinance is what gives their form.', 'company-accounting'),
  ('JP-KSK-PL', 'JP', 'default', '損益計算書（会社計算規則）', 'income_statement', 'JP-KAISHA-KEISAN', date '1970-01-01', null, '会社計算規則 (Ordinance on Company Accounting, Ministry of Justice Ordinance No. 13 of 2006), arts. 87 to 94 — sales, cost of sales, selling and administrative expenses, non-operating income and expenses, extraordinary gains and losses (art. 88), and the five results the Ordinance names: gross profit (art. 89), operating profit (art. 90), ordinary profit (art. 91), profit before tax (art. 92) and net profit (art. 94), income taxes being shown after profit before tax (art. 93).', 'company-accounting')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

