update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = '消費税法 art. 57-4(1) — a qualified invoice states the issuer''s name and registration number, the date of the supply, what was supplied (saying which items are at the reduced rate), the total per rate with the rate, the 消費税額等 per rate, and the name of the recipient. No invoice number is among those particulars, which is why numbering is `free`; the pattern is one a business may choose.',
  numbering_source_key          = 'ctax-act',
  payment_terms_legal_reference = 'No statute sets a payment term between businesses in general in the absence of an agreement, so legal_payment_days and late_payment_reference are empty. Terms imposed on certain subcontracting relationships by a separate act are not carried and were not read for this pack.',
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = '消費税法 art. 5(1) — a business owes the tax on the taxable supplies it has made, and art. 45(1)(i) — the return reports the supplies made during the taxable period: the tax follows the supply, not the invoice and not the payment. For goods that is the delivery, which is what `delivery_date` says; the Act''s special rules for instalment sales, long-term construction contracts and a small business accounting on receipts (arts. 16 to 18) are not carried.',
  tax_point_source_key          = 'ctax-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = 'pint-jp',
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Japanese statute obliges a business to issue or accept an electronic invoice. 消費税法 art. 57-4(5) lets a qualified invoice issuer provide the particulars of a qualified invoice as an electromagnetic record instead of paper, which is what a Peppol invoice is. The Digital Agency is the Japan Peppol Authority and maintains JP PINT, the Japanese specification of the Peppol International model (Peppol BIS Standard Invoice JP PINT 1.1.3, customization urn:peppol:pint:billing-1@jp-1). Its tax categories are S (standard), AA (lower rate), E, G and O. A party is addressed by its 法人番号 (corporate number, EAS 0188), as the JP PINT examples show, and the seller''s tax registration identifier is the registration number of the qualified invoice issuer (EAS 0221), which the NTA''s register publishes as T followed by thirteen digits. JP PINT asks the tax per rate to be rounded to the yen, between the floor and the ceiling, and leaves the direction to the issuer.',
  einvoice_source_key           = 'jp-pint',
  party_scheme                  = '0188',
  vat_scheme                    = '0221',
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'april'
 where country = 'JP';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('JP', 'export', 'export', '輸出免税（消費税法第7条第1項）', '{"en":"Exempt as an export (Consumption Tax Act, art. 7(1))"}'::jsonb, 10, date '1970-01-01', null, '消費税法 art. 7(1) — the supply is exempt as an export; art. 57-4(1)(iv) asks the invoice for the total per rate, and the sentence says why no tax is charged on this line.'),
  ('JP', 'non_taxable', 'exempt', '非課税取引（消費税法第6条第1項・別表第二）', '{"en":"Non-taxable supply (Consumption Tax Act, art. 6(1) and Appended Table 2)"}'::jsonb, 20, date '1970-01-01', null, '消費税法 art. 6(1) and 別表第二 — the supply is non-taxable, so it is not a taxable supply and carries no 消費税額等 on a qualified invoice (art. 57-4(1) reaches only taxable supplies).')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
